def preserve_existing_decisions(apps, schema_editor):
    Request = apps.get_model("users", "AccessRequest")
    Decision = apps.get_model("users", "AccessRequestDecision")
    alias = schema_editor.connection.alias
    for request in Request.objects.using(alias).exclude(status="PENDING").iterator():
        decision, created = Decision.objects.using(alias).get_or_create(
            request_id=request.pk,
            version=0,
            defaults={
                "previous_status": "PENDING",
                "status": request.status,
                "reviewer_id": request.reviewed_by_id,
            },
        )
        if created and request.reviewed_at:
            Decision.objects.using(alias).filter(pk=decision.pk).update(
                decided_at=request.reviewed_at
            )


